<?php
function editor_suite_schema():void{static $done=false;if($done)return;$done=true;try{db()->exec("CREATE TABLE IF NOT EXISTS editor_drafts(page_slug VARCHAR(80) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,html_content LONGTEXT NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_editor_draft_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");db()->exec("CREATE TABLE IF NOT EXISTS editor_revisions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,page_slug VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,html_content LONGTEXT NOT NULL,source ENUM('backend','frontend','autosave','rollback') NOT NULL DEFAULT 'backend',created_at DATETIME NOT NULL,INDEX(page_slug,created_at),INDEX(user_id),CONSTRAINT fk_editor_rev_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");}catch(Throwable $e){}}
function editor_sanitize_html(string $html):string{
 $html=trim($html); if($html==='')return '';
 $allowed=['p','br','strong','b','em','i','u','s','strike','del','ins','sup','sub','code','pre','blockquote','h1','h2','h3','h4','h5','h6','ul','ol','li','a','img','table','thead','tbody','tfoot','tr','th','td','hr','div','span','figure','figcaption'];
 if(class_exists('DOMDocument')){libxml_use_internal_errors(true);$d=new DOMDocument('1.0','UTF-8');$d->loadHTML('<?xml encoding="utf-8"?><div id="pc-root">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);$root=$d->getElementById('pc-root');$walk=function(DOMNode $n)use(&$walk,$allowed){for($c=$n->firstChild;$c;){$next=$c->nextSibling;if($c->nodeType===XML_ELEMENT_NODE){$tag=strtolower($c->nodeName);if(in_array($tag,['script','style','iframe','object','embed','link','meta','form'],true)){$n->removeChild($c);$c=$next;continue;}if(!in_array($tag,$allowed,true)){$frag=$n->ownerDocument->createDocumentFragment();while($c->firstChild)$frag->appendChild($c->firstChild);$n->replaceChild($frag,$c);$c=$next;continue;}
 foreach(iterator_to_array($c->attributes??[]) as $a){$an=strtolower($a->name);$av=(string)$a->value;if(str_starts_with($an,'on')||$an==='style'||in_array($an,['srcdoc','action','formaction'],true)){$c->removeAttribute($a->name);continue;}if(in_array($an,['href','src'],true)&&preg_match('/^\s*javascript:/i',$av))$c->removeAttribute($a->name);if($an==='target'&&!in_array($av,['_blank','_self','_parent','_top'],true))$c->removeAttribute($a->name);}
 if($tag==='a'&&$c->hasAttribute('target')&&!$c->hasAttribute('rel'))$c->setAttribute('rel','noopener');$walk($c);}
 $c=$next;}};$walk($root);$out='';foreach($root->childNodes as $c)$out.=$d->saveHTML($c);libxml_clear_errors();return trim($out);}
 $html=preg_replace('/<\s*script[^>]*>.*?<\s*\/script\s*>/is','',$html);$html=preg_replace('/\s+on[a-z]+\s*=\s*("[^"]*"|\'[^\']*\'|[^\s>]+)/i','',$html);return trim($html);
}
function editor_revision(string $slug,string $title,string $html,string $source='backend'):void{try{editor_suite_schema();$u=current_user();if(!$u)return;db()->prepare('INSERT INTO editor_revisions(page_slug,user_id,title,html_content,source,created_at) VALUES(?,?,?,?,?,NOW())')->execute([$slug,(int)$u['id'],$title,$html,$source]);db()->prepare('DELETE FROM editor_revisions WHERE page_slug=? AND id NOT IN (SELECT id FROM (SELECT id FROM editor_revisions WHERE page_slug=? ORDER BY id DESC LIMIT 10) x)')->execute([$slug,$slug]);}catch(Throwable $e){}}
